const BUNDLE_ID = "cassius-vampire-dragon-cr15-v1";
const VERSION = "v1.0";
const ACTOR_NAME = "Ноктарис, Кровавое Крыло Кассиуса [CR 15] v1.0";
const JOURNAL_NAME = "Памятка: Ноктарис, дракон-вампир Кассиуса v1.0";
const FOLDER_NAME = "Боссы AI Patcher";
const AVATAR = "assets/noktaris-avatar.png";
const TOKEN = "assets/noktaris-token.png";
const SAVE_DC = 18;

function asset(bundle, localPath) {
  return bundle?.assets?.[localPath] ?? `modules/ai-patcher/inbox/${BUNDLE_ID}/${localPath}`;
}

function clone(data) {
  return foundry.utils.deepClone(data);
}

function activityValues(activities) {
  if (!activities) return [];
  if (activities.contents) return activities.contents;
  if (activities.values) return Array.from(activities.values());
  return Object.values(activities);
}

async function getOrCreateFolder(name, type) {
  const existing = game.folders.find((folder) => folder.type === type && folder.name === name);
  if (existing) return existing;
  return Folder.create({ name, type });
}

function macroFlags(name, command, passes = "[postActiveEffects]ItemMacro") {
  const macro = {
    name,
    type: "script",
    img: "icons/creatures/reptiles/dragon-horned-red.webp",
    scope: "global",
    command,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER },
    flags: { dnd5e: { itemMacro: true }, "ai-patcher": { bundleId: BUNDLE_ID } }
  };
  return {
    itemacro: { macro },
    dae: { macro },
    "midi-qol": { onUseMacroName: `${name},${passes}` }
  };
}

const NOKTARIS_MACRO = String.raw`
const data = args?.[0] ?? {};
const pass = data.macroPass ?? "";
const workflow = data.workflow ?? globalThis.workflow ?? {};
const sourceItem = item ?? workflow.item;
const sourceActor = actor ?? workflow.actor;
const sourceName = String(sourceItem?.name ?? "");
const BUNDLE_ID = "cassius-vampire-dragon-cr15-v1";

function actorEffects(actor) {
  if (!actor?.effects) return [];
  if (Array.isArray(actor.effects.contents)) return actor.effects.contents;
  if (actor.effects.values) return Array.from(actor.effects.values());
  return Array.from(actor.effects);
}

function sourceToken() {
  const macroToken = typeof token !== "undefined" ? token : null;
  return macroToken ?? workflow.token ?? canvas.tokens?.controlled?.[0] ?? canvas.tokens?.placeables?.find((candidate) => candidate.actor?.id === sourceActor?.id);
}

function distance(a, b) {
  if (!a || !b) return Infinity;
  if (canvas.grid?.measurePath) return Number(canvas.grid.measurePath([a.center, b.center])?.distance ?? Infinity);
  const gridSize = canvas.grid?.size || 100;
  const gridDistance = canvas.scene?.grid?.distance || 5;
  return Math.hypot(a.center.x - b.center.x, a.center.y - b.center.y) / gridSize * gridDistance;
}

function hostileTokensInRange(range) {
  const self = sourceToken();
  if (!self) return [];
  const disposition = self.document?.disposition ?? -1;
  return (canvas.tokens?.placeables ?? []).filter((target) => {
    if (!target.actor || target.id === self.id || target.document?.hidden) return false;
    if (Number(target.actor.system?.attributes?.hp?.value ?? 1) <= 0) return false;
    if ((target.document?.disposition ?? 0) === disposition) return false;
    return distance(self, target) <= range;
  });
}

async function autoTarget(range, label) {
  const targets = hostileTokensInRange(range);
  if (!targets.length) return;
  const ids = targets.map((target) => target.id);
  game.user.updateTokenTargets(ids);
  canvas.tokens?.setTargets?.(ids);
  ui.notifications?.info(label + ": автоматически выбрано целей: " + ids.length);
}

async function updateHp(actor, delta) {
  if (!actor) return;
  const hp = actor.system?.attributes?.hp ?? {};
  const current = Number(hp.value ?? 0);
  const max = Number(hp.max ?? current);
  const next = Math.max(0, Math.min(max, current + delta));
  await actor.update({ "system.attributes.hp.value": next });
}

async function applyEffect(targetActor, data) {
  if (!targetActor) return;
  const old = actorEffects(targetActor).filter((effect) => effect.getFlag?.("ai-patcher", data.flag));
  if (old.length) await targetActor.deleteEmbeddedDocuments("ActiveEffect", old.map((effect) => effect.id));
  await targetActor.createEmbeddedDocuments("ActiveEffect", [{
    name: data.name,
    img: data.img ?? sourceItem?.img ?? "icons/creatures/reptiles/dragon-horned-red.webp",
    origin: sourceItem?.uuid,
    duration: data.duration ?? { rounds: 1, turns: 1 },
    statuses: data.statuses ?? [],
    changes: data.changes ?? [],
    description: data.description ?? "",
    flags: {
      "ai-patcher": { bundleId: BUNDLE_ID, [data.flag]: true },
      world: data.world ?? {},
      dae: data.dae ?? {}
    }
  }]);
}

function failedTargets() {
  return Array.from(workflow.failedSaves ?? []);
}

function hitTargets() {
  return Array.from(workflow.hitTargets ?? []);
}

async function useNamedItem(name) {
  const nextItem = sourceActor?.items?.find?.((candidate) => candidate.name === name);
  if (!nextItem) return ui.notifications?.warn("Ноктарис: не найден предмет " + name + ".");
  if (globalThis.MidiQOL?.completeItemUse) return MidiQOL.completeItemUse(nextItem, {}, {});
  if (nextItem.use) return nextItem.use();
  return ui.notifications?.warn("Ноктарис: этот лист не поддерживает автоматический запуск " + name + ".");
}

if (pass === "preTargeting") {
  if (/Багровое дыхание/.test(sourceName)) await autoTarget(60, "Багровое дыхание");
  if (/Крыло мрака/.test(sourceName)) await autoTarget(10, "Крыло мрака");
