    content: "<p><strong>Мультиатака.</strong> Ноктарис выполняет два Когтя и один Укус. Если выбран токен цели, следующие атаки откроют стандартный бросок по текущей цели.</p>"
  });
  await useNamedItem("Коготь");
  await useNamedItem("Коготь");
  await useNamedItem("Укус");
  return;
}

if (/Укус/.test(sourceName)) {
  const hits = hitTargets();
  for (const target of hits) {
    await applyEffect(target.actor, {
      name: "Кровавая метка Ноктариса",
      flag: "noktarisBloodMarked",
      statuses: [],
      duration: { rounds: 10 },
      world: { noktarisBloodMarkedBy: sourceActor?.id },
      description: "Цель пахнет кровью дракона-вампира. Ноктарис чувствует её в пределах сцены; некоторые способности получают дополнительные цели или смысл против отмеченных существ."
    });
  }
  if (hits.length) {
    await updateHp(sourceActor, 20);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }),
      content: "<p><strong>Вампирский укус.</strong> Цели получили Кровавую метку. Ноктарис восстановил <strong>20 хитов</strong>.</p>"
    });
  }
  return;
}

if (/Багровое дыхание/.test(sourceName)) {
  for (const target of failedTargets()) {
    await applyEffect(target.actor, {
      name: "Кровяная слабость",
      flag: "noktarisBloodWeakness",
      statuses: ["poisoned"],
      duration: { rounds: 3 },
      description: "Кровь цели сворачивается чёрными прожилками. Цель отравлена на 3 раунда и является особенно заметной для вампирских чувств Ноктариса."
