}

if (/Кровавый поводок/.test(sourceName)) {
  for (const target of failedTargets()) {
    await applyEffect(target.actor, {
      name: "Кровавый поводок",
      flag: "noktarisBloodLeash",
      statuses: ["restrained"],
      duration: { rounds: 2 },
      description: "Кровь цели вытягивается к Ноктарису алыми нитями. Цель удержана на 2 раунда. Ведущий может переместить её до 30 фт к Ноктарису."
    });
  }
  return;
}

if (/Регенерация вампира/.test(sourceName)) {
  await updateHp(sourceActor, 20);
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }),
    content: "<p><strong>Регенерация вампира.</strong> Ноктарис восстановил <strong>20 хитов</strong>, если в этом раунде не получал урон излучением.</p>"
  });
  return;
}

if (/Солнечная уязвимость/.test(sourceName)) {
  await updateHp(sourceActor, -20);
  await applyEffect(sourceActor, {
    name: "Под прямым солнцем",
    flag: "noktarisSunlight",
    statuses: [],
    duration: { rounds: 1 },
    changes: [
      { key: "flags.midi-qol.disadvantage.attack.all", mode: CONST.ACTIVE_EFFECT_MODES.CUSTOM, value: "1", priority: 20 },
