}

if (/Легендарное сопротивление/.test(sourceName)) {
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: sourceActor, token: sourceToken()?.document }),
    content: "<p><strong>Легендарное сопротивление.</strong> Если Ноктарис провалил спасбросок, он может вместо этого считать его успешным. Лимит: 3 раза в день.</p>"
  });
  return;
}

if (/Крыло мрака/.test(sourceName)) {
  for (const target of failedTargets()) {
    await applyEffect(target.actor, {
      name: "Сбит крылом Ноктариса",
      flag: "noktarisWingProne",
