if (/Команда Кассиуса/.test(sourceName)) {
  for (const target of failedTargets()) {
    await applyEffect(target.actor, {
      name: "Приказ Кассиуса",
      flag: "noktarisCassiusCommand",
      statuses: ["charmed", "frightened"],
      duration: { rounds: 1, turns: 1 },
      description: "Цель слышит голос Кассиуса через пасть Ноктариса. До конца следующего хода Ноктариса она очарована и испугана, не может добровольно атаковать Ноктариса или Кассиуса."
    });
