function setUses(item, max, recovery) {
  item.system.uses = { spent: 0, max: String(max), recovery };
}

function fixActivityId(activity) {
  const id = foundry.utils.randomID(16);
  activity._id = id;
  return id;
}

function finishSingleActivity(item, source, activityName, uses = null) {
  const activity = activityValues(source.system.activities)[0];
  const id = fixActivityId(activity);
  activity.name = activityName;
  activity.img = item.img;
  if (uses) activity.uses = uses;
  item.system.activities = { [id]: activity };
}

function addAttackActivity(item, { activityName, activation = "action", reach = 5, ability = "str", damageParts = [] }) {
  const source = clone(item);
  source.system.actionType = "mwak";
  source.system.activation = { type: activation, cost: 1, condition: "" };
  source.system.attack = { bonus: "", flat: false };
  source.system.ability = ability;
  source.system.range = { value: null, long: null, reach, units: "ft" };
  source.system.target = { value: 1, type: "creature", units: "", prompt: true };
  source.system.damage = { parts: damageParts };
  CONFIG.DND5E.activityTypes.attack.documentClass.createInitialActivity(source, { offset: 0 });
  finishSingleActivity(item, source, activityName);
}

function addSaveActivity(item, { activityName, activation = "action", range = 60, ability = "wis", prompt = true, damageParts = [] }) {
  const source = clone(item);
  source.system.actionType = "save";
  source.system.activation = { type: activation, cost: 1, condition: "" };
  source.system.range = { value: range, units: "ft" };
  source.system.target = { value: null, type: "creature", units: "", prompt };
  source.system.save = { ability, dc: SAVE_DC, scaling: "flat" };
  source.system.damage = { parts: damageParts };
  CONFIG.DND5E.activityTypes.save.documentClass.createInitialActivity(source, { offset: 0 });
  finishSingleActivity(item, source, activityName);
}

function addUtilityActivity(item, { activityName, activation = "action", uses = null }) {
  const source = clone(item);
  source.system.activation = { type: activation, cost: 1, condition: "" };
  CONFIG.DND5E.activityTypes.utility.documentClass.createInitialActivity(source, { offset: 0 });
  finishSingleActivity(item, source, activityName, uses);
}

function buildItems() {
  const items = [];

  const multi = baseItem("Мультиатака", "icons/skills/melee/strike-weapons-orange.webp", "<p>Ноктарис совершает две атаки <strong>Когтем</strong> и одну атаку <strong>Укусом</strong>. Макрос пытается запустить эти атаки подряд по текущей выбранной цели.</p>");
  addUtilityActivity(multi, { activityName: "Мультиатака" });
  multi.flags = { ...multi.flags, ...macroFlags("Ноктарис ItemMacro", NOKTARIS_MACRO) };
  items.push(multi);

  const claw = baseItem("Коготь", "icons/skills/melee/claws-swipe-red.webp", "<p><strong>Рукопашная атака оружием:</strong> +12 к попаданию, досягаемость 10 фт, одна цель. Урон: 2d10 + 7 рубящий + 2d6 некротический.</p>");
  addAttackActivity(claw, { activityName: "Коготь", reach: 10, damageParts: [["2d10 + 7", "slashing"], ["2d6", "necrotic"]] });
  items.push(claw);

  const bite = baseItem("Укус", "icons/creatures/abilities/fang-tooth-blood-red.webp", "<p><strong>Рукопашная атака оружием:</strong> +12 к попаданию, досягаемость 10 фт, одна цель. Урон: 2d8 + 7 колющий + 4d6 некротический. При попадании цель получает <strong>Кровавую метку Ноктариса</strong>, а Ноктарис восстанавливает 20 хитов.</p>");
  addAttackActivity(bite, { activityName: "Укус", reach: 10, damageParts: [["2d8 + 7", "piercing"], ["4d6", "necrotic"]] });
  bite.flags = { ...bite.flags, ...macroFlags("Ноктарис ItemMacro", NOKTARIS_MACRO) };
  items.push(bite);

  const tail = baseItem("Хвост", "icons/creatures/abilities/tail-swipe-green.webp", "<p><strong>Рукопашная атака оружием:</strong> +12 к попаданию, досягаемость 15 фт, одна цель. Урон: 2d10 + 7 дробящий.</p>");
  addAttackActivity(tail, { activityName: "Хвост", reach: 15, damageParts: [["2d10 + 7", "bludgeoning"]] });
  items.push(tail);

  const breath = baseItem("Багровое дыхание (перезарядка 5-6)", "icons/magic/unholy/strike-beam-blood-red-purple.webp", "<p><strong>Перезарядка 5-6.</strong> Ноктарис выдыхает 60-футовый конус свёрнутой крови и некротического тумана. Существа совершают спасбросок Телосложения СЛ 18, получая 10d8 некротического урона при провале или половину при успехе. Провалившие также получают <strong>Кровяную слабость</strong> на 3 раунда.</p>");
  setUses(breath, 1, [{ period: "recharge", formula: "5", type: "recoverAll" }]);
  addSaveActivity(breath, { activityName: "Багровое дыхание", range: 60, ability: "con", prompt: false, damageParts: [["10d8", "necrotic"]] });
