async function createOrUpdateJournal(folderId, actor, dryRun) {
  const existing = game.journal.find((entry) => entry.getFlag("ai-patcher", "bundleId") === BUNDLE_ID || entry.name === JOURNAL_NAME);
  if (dryRun) return { action: existing ? "update" : "create", type: "JournalEntry", name: JOURNAL_NAME };
  const data = {
    name: JOURNAL_NAME,
    folder: folderId,
    flags: { "ai-patcher": { bundleId: BUNDLE_ID, role: "noktaris-handout" } },
    pages: [{
      name: "Ноктарис",
      type: "text",
      text: { format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML, content: journalContent(actor) }
    }]
  };
  if (existing) return existing.update(data);
  return JournalEntry.create(data);
}

export default async function patch({ dryRun, log, bundle }) {
  if (game.system.id !== "dnd5e") throw new Error("Ноктарис создан для системы dnd5e.");

  const existing = game.actors.find((actor) =>
    actor.getFlag("ai-patcher", "bundleId") === BUNDLE_ID ||
    actor.name === ACTOR_NAME
  );
  const actorFolder = await getOrCreateFolder(FOLDER_NAME, "Actor");
  const journalFolder = await getOrCreateFolder(FOLDER_NAME, "JournalEntry");
  const actorData = baseActorData(bundle);
  actorData.folder = actorFolder.id;
  const itemData = buildItems();

  if (dryRun) {
    return {
      action: existing ? "update actor and replace Noktaris items" : "create actor",
      actor: ACTOR_NAME,
      cr: 15,
      items: itemData.map((item) => item.name),
      avatar: asset(bundle, AVATAR),
      token: asset(bundle, TOKEN)
    };
  }

  let actor = existing;
  if (actor) {
    log(`Обновление босса: ${actor.name}`);
    await actor.update(actorData);
    const oldItems = actor.items.filter((item) => item.getFlag("ai-patcher", "bundleId") === BUNDLE_ID);
    if (oldItems.length) await actor.deleteEmbeddedDocuments("Item", oldItems.map((item) => item.id));
    await actor.createEmbeddedDocuments("Item", itemData);
  } else {
    log(`Создание босса: ${ACTOR_NAME}`);
    actorData.items = itemData;
    actor = await Actor.create(actorData);
  }

  if (!actor) throw new Error("Не удалось создать Ноктариса: Foundry не вернул документ Actor.");
  await actor.setFlag("ai-patcher", "bundleId", BUNDLE_ID);
  await createOrUpdateJournal(journalFolder.id, actor, false);

  return {
    actor: actor.uuid,
    name: actor.name,
    cr: actor.system.details.cr,
    itemCount: actor.items.size,
    avatar: actor.img,
    token: actor.prototypeToken.texture.src,
    version: VERSION
  };
}
